import java.util.*;

class Edge {
    int y, capacity, flow, cost;
    Edge() {}
    Edge(int y, int c, int f, int cost) {
        this.y = y;
        this.capacity = c;
        this.flow = f;
        this.cost = cost;
    }
}

public class Main {
    static List<Edge> edgesList = new ArrayList<>();
    static final int MAXNODES = 14043;
    static List<Integer>[] adjList = new ArrayList[MAXNODES];
    static long totalCostValue = 0;
    static long[] distArr = new long[MAXNODES];
    static int[] parentNodeArr = new int[MAXNODES];
    static int[] parentEdgeArr = new int[MAXNODES];
    static int[] inqArr = new int[MAXNODES];

    static final long INF_VAL = (long)1e18;
    static int sNode = MAXNODES - 2;
    static int tNode = MAXNODES - 1;

    static {
        for (int i = 0; i < MAXNODES; i++) {
            adjList[i] = new ArrayList<>();
        }
    }

    static int residualCapacity(int idx) {
        return edgesList.get(idx).capacity - edgesList.get(idx).flow;
    }

    static void findPathAndPushFlow() {
        for (int i = 0; i < MAXNODES; i++) {
            distArr[i] = INF_VAL;
            parentNodeArr[i] = -1;
            parentEdgeArr[i] = -1;
            inqArr[i] = 0;
        }
        distArr[sNode] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(sNode);
        inqArr[sNode] = 1;
        while (!q.isEmpty()) {
            int u = q.poll();
            inqArr[u] = 0;
            for (int eIdx : adjList[u]) {
                if (residualCapacity(eIdx) == 0) continue;
                int y = edgesList.get(eIdx).y;
                int cst = edgesList.get(eIdx).cost;
                if (distArr[y] > distArr[u] + cst) {
                    distArr[y] = distArr[u] + cst;
                    parentNodeArr[y] = u;
                    parentEdgeArr[y] = eIdx;
                    if (inqArr[y] == 0) {
                        inqArr[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }
        int cur = tNode;
        while (cur != sNode) {
            edgesList.get(parentEdgeArr[cur]).flow++;
            edgesList.get(parentEdgeArr[cur] ^ 1).flow--;
            cur = parentNodeArr[cur];
        }
        totalCostValue += distArr[tNode];
    }

    static void createEdge(int from, int to, int cap, int cst) {
        adjList[from].add(edgesList.size());
        edgesList.add(new Edge(to, cap, 0, cst));
        adjList[to].add(edgesList.size());
        edgesList.add(new Edge(from, 0, 0, -cst));
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        for (int i = 0; i < k; i++) {
            int x = sc.nextInt() - 1;
            createEdge(sNode, x, 1, 0);
        }

        int T = 101;
        for (int i = 0; i < T; i++) {
            createEdge(i * n, tNode, k, i * c);
        }

        for (int i = 0; i < m; i++) {
            int x = sc.nextInt() - 1;
            int y = sc.nextInt() - 1;
            for (int j = 0; j < T - 1; j++) {
                createEdge(x + j * n, y + j * n + n, 1, d * (j * 2 + 1));
            }
            for (int j = 0; j < T - 1; j++) {
                createEdge(y + j * n, x + j * n + n, 1, d * (j * 2 + 1));
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < T - 1; j++) {
                createEdge(i + j * n, i + j * n + n, k, 0);
            }
        }

        for (int i = 0; i < k; i++) {
            findPathAndPushFlow();
        }

        System.out.println(totalCostValue);
        sc.close();
    }
}
